import React, { useEffect, useState, useCallback } from 'react';
import { adminFetch } from './utils/api';
import StatusBadge from '../../components/admin/StatusBadge';
import Pagination from '../../components/admin/Pagination';
import ConfirmModal from '../../components/admin/ConfirmModal';

function IconBolt({ size = 13 }) {
  return (
    <svg width={size} height={size} viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round" style={{ display: 'inline', verticalAlign: 'middle', marginRight: 5, flexShrink: 0 }}>
      <polygon points="13 2 3 14 12 14 11 22 21 10 12 10 13 2"/>
    </svg>
  );
}
function IconUser({ size = 13 }) {
  return (
    <svg width={size} height={size} viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round" style={{ display: 'inline', verticalAlign: 'middle', marginRight: 5, flexShrink: 0 }}>
      <path d="M20 21v-2a4 4 0 0 0-4-4H8a4 4 0 0 0-4 4v2"/><circle cx="12" cy="7" r="4"/>
    </svg>
  );
}
function IconKey({ size = 13 }) {
  return (
    <svg width={size} height={size} viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round" style={{ display: 'inline', verticalAlign: 'middle', marginRight: 5, flexShrink: 0 }}>
      <circle cx="7.5" cy="15.5" r="5.5"/><path d="M21 2l-9.6 9.6"/><path d="M15.5 7.5l3 3L22 7l-3-3"/>
    </svg>
  );
}

const CRYPTO_COLORS = {
  BTC:  { bg: 'rgba(247,147,26,.15)',  color: '#f7931a' },
  ETH:  { bg: 'rgba(98,126,234,.15)',  color: '#627eea' },
  DOGE: { bg: 'rgba(194,166,51,.15)',  color: '#c2a633' },
  LTC:  { bg: 'rgba(52,93,157,.15)',   color: '#345d9d' },
  XMR:  { bg: 'rgba(255,102,0,.15)',   color: '#ff6600' },
};

function CurrencyBadge({ currency }) {
  const s = CRYPTO_COLORS[currency] || { bg: 'rgba(108,117,125,.12)', color: '#6c757d' };
  return (
    <span className="admin-badge" style={{ background: s.bg, color: s.color, fontWeight: 700, fontFamily: 'monospace' }}>
      {currency}
    </span>
  );
}

function truncateAddr(addr) {
  if (!addr || addr.length <= 14) return addr || '—';
  return `${addr.slice(0, 6)}…${addr.slice(-6)}`;
}

const fmt    = n => `$${Number(n || 0).toFixed(2)}`;
const fmtC   = n => (n == null ? '—' : Number(n).toFixed(8).replace(/\.?0+$/, '') || '0');
const fmtUsd = n => (n == null ? '—' : fmt(n));

function InfoRows({ rows }) {
  return (
    <div className="admin-info-list" style={{ marginBottom: 14 }}>
      {rows.filter(Boolean).map(([label, value, color]) => (
        <div key={label} className="admin-info-row">
          <span className="admin-info-label">{label}</span>
          <span className="admin-info-value" style={color ? { color } : undefined}>{value}</span>
        </div>
      ))}
    </div>
  );
}

function InspectModal({ title, modal, onClose, children }) {
  return (
    <div className="admin-modal-overlay" onClick={e => { if (e.target === e.currentTarget) onClose(); }}>
      <div className="admin-modal">
        <div className="admin-modal-title" style={{ display: 'flex', alignItems: 'center', gap: 10, flexWrap: 'wrap' }}>
          <CurrencyBadge currency={modal.deposit.currency} /> {title}
          <span style={{ fontSize: 12, color: '#6c757d', fontWeight: 600 }}>#{modal.deposit.id} · {modal.deposit.user?.username || '—'}</span>
        </div>
        {modal.loading && <div style={{ color: '#6c757d', fontSize: 13, padding: '12px 0' }}>Loading…</div>}
        {modal.error && (
          <div style={{ background: 'rgba(229,57,53,.08)', border: '1px solid rgba(229,57,53,.25)', borderRadius: 8, padding: '10px 12px', color: '#c62828', fontSize: 13, marginBottom: 14 }}>
            {modal.error}
          </div>
        )}
        {modal.data && children(modal.data)}
        <div className="admin-modal-actions">
          <button className="admin-btn admin-btn-secondary" onClick={onClose}>Close</button>
        </div>
      </div>
    </div>
  );
}

export default function AdminDeposits() {
  const [deposits, setDeposits]     = useState([]);
  const [total, setTotal]           = useState(0);
  const [page, setPage]             = useState(1);
  const [statusFilter, setStatusFilter] = useState('');
  const [currency, setCurrency]     = useState('');
  const [loading, setLoading]       = useState(true);
  const [err, setErr]               = useState(null);

  // Confirm modal
  const [confirmModal, setConfirmModal] = useState(null); // { id, currency }
  const [confirmForm, setConfirmForm]   = useState({ amount: '', note: '', unit: 'usd' });
  const [confirmPrice, setConfirmPrice] = useState(null); // live USD price of the deposit's coin
  const [confirming, setConfirming]     = useState(false);
  const [confirmErr, setConfirmErr]     = useState(null);

  // USD value / on-chain wallet modals: { deposit, loading, data, error }
  const [usdModal, setUsdModal]     = useState(null);
  const [chainModal, setChainModal] = useState(null);

  // Expire confirm
  const [expireId, setExpireId]   = useState(null);
  const [expiring, setExpiring]   = useState(false);

  // Cleanup expired
  const [cleanupLoading, setCleanupLoading] = useState(false);
  const [cleanupMsg, setCleanupMsg]         = useState(null);
  const [cleanupConfirm, setCleanupConfirm] = useState(false);

  // View address modal
  const [addrModal, setAddrModal] = useState(null); // { address, currency }
  const [copied, setCopied]       = useState(false);

  // Verify HD key modal
  const [verifying, setVerifying]         = useState(null); // depositId being fetched
  const [verifyResult, setVerifyResult]   = useState(null); // result object

  const limit = 20;

  const load = useCallback(async () => {
    setLoading(true); setErr(null);
    try {
      const p = new URLSearchParams({ page, limit });
      if (statusFilter) p.set('status', statusFilter);
      if (currency)     p.set('currency', currency);
      const d = await adminFetch(`/admin/deposits?${p}`);
      setDeposits(d.deposits || []);
      setTotal(d.total || 0);
    } catch (e) { setErr(e.message); }
    finally { setLoading(false); }
  }, [page, statusFilter, currency]);

  useEffect(() => { load(); }, [load]);

  const doConfirm = async e => {
    e.preventDefault(); setConfirming(true); setConfirmErr(null);
    try {
      await adminFetch(`/admin/deposits/${confirmModal.id}/confirm`, {
        method: 'PATCH',
        body: {
          ...(confirmForm.unit === 'usd' ? { usdAmount: parseFloat(confirmForm.amount) } : { amount: parseFloat(confirmForm.amount) }),
          note: confirmForm.note || undefined,
        },
      });
      setConfirmModal(null);
      load();
    } catch (e) { setConfirmErr(e.message); }
    finally { setConfirming(false); }
  };

  const openInspect = async (d, kind) => {
    const setModal = kind === 'usd' ? setUsdModal : setChainModal;
    setModal({ deposit: d, loading: true, data: null, error: null });
    try {
      const data = await adminFetch(`/admin/deposits/${d.id}/${kind === 'usd' ? 'usd-value' : 'onchain'}`);
      setModal({ deposit: d, loading: false, data, error: null });
    } catch (e) {
      setModal({ deposit: d, loading: false, data: null, error: e.message });
    }
  };

  const doExpire = async () => {
    setExpiring(true); setErr(null);
    try {
      await adminFetch(`/admin/deposits/${expireId}/expire`, { method: 'PATCH' });
      setExpireId(null);
      load();
    } catch (e) { setErr(e.message); }
    finally { setExpiring(false); }
  };

  const copyAddr = async () => {
    const text = addrModal?.address || '';
    try {
      await navigator.clipboard.writeText(text);
    } catch {
      // Clipboard API unavailable (non-HTTPS or denied): fall back to a hidden textarea
      const ta = document.createElement('textarea');
      ta.value = text; ta.style.position = 'fixed'; ta.style.opacity = '0';
      document.body.appendChild(ta); ta.select();
      try { document.execCommand('copy'); } finally { document.body.removeChild(ta); }
    }
    setCopied(true);
    setTimeout(() => setCopied(false), 2000);
  };

  const doCleanup = async () => {
    setCleanupLoading(true); setCleanupMsg(null); setCleanupConfirm(false);
    try {
      const data = await adminFetch('/admin/deposits/cleanup', { method: 'POST' });
      setCleanupMsg(`${data.cleaned} deposit${data.cleaned !== 1 ? 's' : ''} expired and forwards released.`);
      load();
    } catch (e) {
      setCleanupMsg(`Error: ${e.message}`);
    } finally { setCleanupLoading(false); }
  };

  // Rereads the address on the blockchain and credits every payment not counted yet
  const [syncing, setSyncing] = useState(null);
  const [syncResult, setSyncResult] = useState(null); // { deposit, data } or { deposit, error }
  const doSync = async d => {
    setSyncing(d.id);
    try {
      const data = await adminFetch(`/admin/deposits/${d.id}/sync`, { method: 'POST' });
      setSyncResult({ deposit: d, data });
      load();
    } catch (e) { setSyncResult({ deposit: d, error: e.message }); }
    finally { setSyncing(null); }
  };

  const doVerify = async (depositId) => {
    setVerifying(depositId);
    try {
      const data = await adminFetch(`/admin/utxo/verify-address/${depositId}`);
      setVerifyResult(data);
    } catch (e) {
      setVerifyResult({ error: e.message });
    } finally {
      setVerifying(null);
    }
  };

  const openConfirm = d => {
    setConfirmForm({ amount: '', note: '', unit: 'usd' });
    setConfirmErr(null);
    setConfirmPrice(null);
    setConfirmModal({ id: d.id, currency: d.currency });
    adminFetch('/wallet/prices').then(r => setConfirmPrice(r?.prices?.[d.currency] || null)).catch(() => {});
  };

  return (
    <div>
      <div className="admin-page-header">
        <div>
          <h1 className="admin-page-title">Deposits</h1>
          <p className="admin-page-subtitle">{total} deposits</p>
        </div>
      </div>

      <div className="admin-filters">
        <select className="admin-filter-select" value={statusFilter} onChange={e => { setStatusFilter(e.target.value); setPage(1); }}>
          <option value="">All statuses</option>
          <option value="awaiting">Awaiting</option>
          <option value="partial">Partial</option>
          <option value="confirmed">Confirmed</option>
          <option value="expired">Expired</option>
        </select>
        <select className="admin-filter-select" value={currency} onChange={e => { setCurrency(e.target.value); setPage(1); }}>
          <option value="">All currencies</option>
          {Object.keys(CRYPTO_COLORS).map(c => <option key={c} value={c}>{c}</option>)}
        </select>
        <button
          className="admin-btn admin-btn-danger admin-btn-sm"
          style={{ marginLeft: 'auto' }}
          disabled={cleanupLoading}
          onClick={() => setCleanupConfirm(true)}
        >
          {cleanupLoading ? 'Cleaning…' : 'Cleanup Expired'}
        </button>
      </div>
      {cleanupMsg && (
        <div style={{ marginBottom: 12, fontSize: 13, color: cleanupMsg.startsWith('Error') ? '#e53935' : '#2e7d32', background: cleanupMsg.startsWith('Error') ? 'rgba(229,57,53,.08)' : 'rgba(46,125,50,.08)', border: `1px solid ${cleanupMsg.startsWith('Error') ? 'rgba(229,57,53,.25)' : 'rgba(46,125,50,.25)'}`, borderRadius: 8, padding: '8px 14px', display: 'flex', justifyContent: 'space-between', alignItems: 'center' }}>
          <span>{cleanupMsg}</span>
          <button style={{ background: 'none', border: 'none', cursor: 'pointer', fontSize: 16, color: 'inherit', lineHeight: 1 }} onClick={() => setCleanupMsg(null)}>×</button>
        </div>
      )}

      {/* Process reference panel */}
      <div style={{ display: 'flex', gap: 10, marginBottom: 16, flexWrap: 'wrap' }}>
        <div style={{ flex: 1, minWidth: 220, background: 'rgba(67,160,71,.08)', border: '1px solid rgba(67,160,71,.25)', borderRadius: 10, padding: '10px 14px' }}>
          <div style={{ fontWeight: 700, fontSize: 12, color: '#2e7d32', marginBottom: 4, display: 'flex', alignItems: 'center' }}><IconBolt />Auto-confirmed (BTC · LTC · DOGE · ETH)</div>
          <div style={{ fontSize: 12, color: '#388e3c', lineHeight: 1.6 }}>
            A unique address is generated per deposit via BlockCypher (BTC/LTC/DOGE) or Alchemy (ETH).
            Once the transaction gets 1 on-chain confirmation, the webhook credits the customer's balance automatically.
            <strong> No action needed.</strong>
          </div>
        </div>
        <div style={{ flex: 1, minWidth: 220, background: 'rgba(251,140,0,.08)', border: '1px solid rgba(251,140,0,.3)', borderRadius: 10, padding: '10px 14px' }}>
          <div style={{ fontWeight: 700, fontSize: 12, color: '#e65100', marginBottom: 4, display: 'flex', alignItems: 'center' }}><IconUser />Manual review required (XMR)</div>
          <div style={{ fontSize: 12, color: '#bf360c', lineHeight: 1.6 }}>
            All XMR deposits share a single address. The customer must open a support ticket with their TX Hash.
            Verify the payment in your Monero wallet, then click <strong>Confirm</strong> on the deposit row and enter the XMR amount received.
          </div>
        </div>
      </div>

      {err && <div style={{ color: '#e53935', marginBottom: 12, fontSize: 13 }}>{err}</div>}

      <div className="admin-table-wrap">
        <table className="admin-table">
          <thead>
            <tr>
              <th>ID</th>
              <th>User</th>
              <th>Currency</th>
              <th>Address</th>
              <th>Expected</th>
              <th>Received</th>
              <th>Credited to customer</th>
              <th>Status</th>
              <th>Expires</th>
              <th>Created</th>
              <th>Actions</th>
            </tr>
          </thead>
          <tbody>
            {loading
              ? Array.from({ length: 6 }, (_, i) => (
                <tr key={i}>{Array.from({ length: 11 }, (__, j) => <td key={j}><span className="admin-skel" style={{ width: '70%', height: 13, display: 'block' }} /></td>)}</tr>
              ))
              : deposits.length === 0
                ? <tr><td colSpan={11} className="admin-table-empty">No deposits found</td></tr>
                : deposits.map(d => (
                  <tr key={d.id}>
                    <td style={{ fontFamily: 'monospace', fontSize: 12, color: '#6c757d' }}>#{d.id}</td>
                    <td>
                      <div style={{ fontWeight: 600, fontSize: 13 }}>{d.user?.username || '—'}</div>
                    </td>
                    <td><CurrencyBadge currency={d.currency} /></td>
                    <td>
                      <button
                        className="admin-btn admin-btn-secondary admin-btn-sm"
                        style={{ fontFamily: 'monospace', fontSize: 11 }}
                        onClick={() => setAddrModal({ address: d.address, currency: d.currency })}
                        title={d.address}
                      >
                        {truncateAddr(d.address)}
                      </button>
                    </td>
                    <td style={{ fontFamily: 'monospace', fontSize: 12, whiteSpace: 'nowrap' }}>
                      {d.amountExpected != null ? `${fmtC(d.amountExpected)} ${d.currency}` : '—'}
                    </td>
                    <td style={{ fontFamily: 'monospace', fontSize: 12, whiteSpace: 'nowrap', color: d.amountReceived > 0 ? '#43a047' : '#6c757d' }}>
                      {fmtC(d.amountReceived)} {d.currency}
                    </td>
                    <td style={{ fontWeight: 700, color: d.netAmount > 0 || d.usdCredited > 0 ? '#43a047' : '#6c757d' }}>
                      {d.netAmount > 0
                        ? <>
                            <div style={{ fontFamily: 'monospace', fontSize: 12 }}>{fmtC(d.netAmount)} {d.currency}</div>
                            <div style={{ fontSize: 11, fontWeight: 400, color: '#6c757d' }}>{fmt(d.usdCredited)} at deposit</div>
                          </>
                        : d.usdCredited > 0 ? fmt(d.usdCredited) : '—'}
                    </td>
                    <td>
                      <div style={{ display: 'flex', gap: 4, alignItems: 'center', flexWrap: 'wrap' }}>
                        <StatusBadge status={d.status} />
                        {d.currency === 'XMR' && (d.status === 'awaiting' || d.status === 'partial') && (
                          <span style={{ fontSize: 10, fontWeight: 700, background: 'rgba(251,140,0,.15)', color: '#e65100', borderRadius: 6, padding: '2px 6px', whiteSpace: 'nowrap' }}>
                            MANUAL
                          </span>
                        )}
                      </div>
                    </td>
                    <td style={{ fontSize: 12, color: '#6c757d' }}>
                      {d.expiresAt ? new Date(d.expiresAt).toLocaleString() : '—'}
                    </td>
                    <td style={{ fontSize: 12, color: '#6c757d', whiteSpace: 'nowrap' }}>
                      {new Date(d.createdAt).toLocaleString()}
                    </td>
                    <td>
                      <div style={{ display: 'flex', gap: 4, flexWrap: 'wrap' }}>
                        {(d.status === 'awaiting' || d.status === 'partial') && (
                          <button className="admin-btn admin-btn-success admin-btn-sm" onClick={() => openConfirm(d)}>
                            Confirm
                          </button>
                        )}
                        {(d.status === 'awaiting' || d.status === 'partial') && (
                          <button className="admin-btn admin-btn-danger admin-btn-sm" onClick={() => setExpireId(d.id)}>
                            Expire
                          </button>
                        )}
                        <button className="admin-btn admin-btn-secondary admin-btn-sm" title="USD value of the funds the customer sent" onClick={() => openInspect(d, 'usd')}>
                          $ Value
                        </button>
                        {d.currency !== 'XMR' && d.address && d.address !== 'pending' && (
                          <button className="admin-btn admin-btn-secondary admin-btn-sm" title="Live balance of the deposit address on the blockchain" onClick={() => openInspect(d, 'chain')}>
                            Wallet
                          </button>
                        )}
                        {d.currency !== 'XMR' && d.address && d.address !== 'pending' && (
                          <button className="admin-btn admin-btn-primary admin-btn-sm" title="Read the address on the blockchain and credit every payment not counted yet"
                            disabled={syncing === d.id} onClick={() => doSync(d)}>
                            {syncing === d.id ? 'Checking…' : 'Check chain'}
                          </button>
                        )}
                        {['BTC', 'LTC', 'DOGE'].includes(d.currency) && (
                          <button
                            className="admin-btn admin-btn-secondary admin-btn-sm"
                            title="Verify that the stored address matches the current HD seed"
                            disabled={verifying === d.id}
                            onClick={() => doVerify(d.id)}
                          >
                            {verifying === d.id ? '…' : <><IconKey />Verify</>}
                          </button>
                        )}
                      </div>
                    </td>
                  </tr>
                ))
            }
          </tbody>
        </table>
      </div>
      <Pagination page={page} totalPages={Math.ceil(total / limit)} onChange={setPage} />

      {/* Check chain result */}
      {syncResult && (() => {
        const { deposit: dd, data: r, error: syncErr } = syncResult;
        return (
          <div className="admin-modal-overlay" onClick={e => { if (e.target === e.currentTarget) setSyncResult(null); }}>
            <div className="admin-modal">
              <div className="admin-modal-title">Check chain: deposit #{dd.id} ({dd.currency})</div>
              {syncErr ? (
                <div style={{ color: '#e53935', fontSize: 13, marginBottom: 12 }}>{syncErr}</div>
              ) : (
                <div style={{ fontSize: 13, lineHeight: 1.7, marginBottom: 12 }}>
                  <div>Payments found on the address: <strong>{r.found}</strong></div>
                  <div>Credited now: <strong style={{ color: r.credited > 0 ? '#2e7d32' : 'inherit' }}>{r.credited}</strong>{r.newlyReceived > 0 && ` (${r.newlyReceived} ${r.currency})`}</div>
                  <div>Total received on this deposit: <strong>{r.amountReceived} {r.currency}</strong></div>
                  <div>Status: <StatusBadge status={r.status} /></div>
                  {r.pending && <div style={{ color: '#e65100' }}>A payment is still waiting for its first confirmation.</div>}
                  {r.failed?.length > 0 && (
                    <div style={{ marginTop: 10, background: 'rgba(229,57,53,.08)', border: '1px solid rgba(229,57,53,.25)', borderRadius: 8, padding: '8px 12px' }}>
                      <strong style={{ color: '#c62828' }}>Not credited:</strong>
                      {r.failed.map(f => (
                        <div key={f.hash} style={{ fontSize: 12, marginTop: 4 }}>
                          {f.amount} {r.currency} <span style={{ color: '#6c757d', fontFamily: 'monospace' }}>({f.hash.slice(0, 12)}…)</span>: {f.reason}
                        </div>
                      ))}
                    </div>
                  )}
                  {r.found === 0 && !r.pending && <div style={{ color: '#6c757d' }}>No confirmed payment on this address yet.</div>}
                </div>
              )}
              <div className="admin-modal-actions">
                <button type="button" className="admin-btn admin-btn-secondary" onClick={() => setSyncResult(null)}>Close</button>
              </div>
            </div>
          </div>
        );
      })()}

      {/* Confirm modal */}
      {confirmModal && (
        <div className="admin-modal-overlay" onClick={e => { if (e.target === e.currentTarget) setConfirmModal(null); }}>
          <div className="admin-modal">
            <div className="admin-modal-title">Confirm Deposit</div>
            {confirmModal.currency === 'XMR' && (
              <div style={{ background: 'rgba(251,140,0,.1)', border: '1px solid rgba(251,140,0,.3)', borderRadius: 8, padding: '10px 12px', marginBottom: 14, fontSize: 12, color: '#bf360c', lineHeight: 1.6 }}>
                <strong>XMR manual confirmation checklist:</strong><br />
                1. Open your Monero wallet and confirm you received a transaction from this customer.<br />
                2. Note the exact XMR amount received.<br />
                3. Enter it below and click Confirm — the customer's balance is credited in XMR (net of the deposit fee).
              </div>
            )}
            <form onSubmit={doConfirm}>
              <div className="admin-form-group">
                <label className="admin-label">Amount received *</label>
                <div style={{ display: 'flex', gap: 8 }}>
                  <input
                    className="admin-input"
                    type="number"
                    min={confirmForm.unit === 'usd' ? '0.01' : '0.00000001'}
                    step={confirmForm.unit === 'usd' ? '0.01' : '0.00000001'}
                    value={confirmForm.amount}
                    onChange={e => setConfirmForm(f => ({ ...f, amount: e.target.value }))}
                    placeholder={confirmForm.unit === 'usd' ? '0.00' : '0.00000000'}
                    required
                    autoFocus
                  />
                  <select className="admin-select" style={{ width: 110 }} value={confirmForm.unit}
                    onChange={e => setConfirmForm(f => ({ ...f, unit: e.target.value, amount: '' }))}>
                    <option value="usd">USD</option>
                    <option value="coin">{confirmModal.currency}</option>
                  </select>
                </div>
                {Number(confirmForm.amount) > 0 && (
                  <div style={{ fontSize: 12, color: '#6c757d', marginTop: 6 }}>
                    {!confirmPrice
                      ? `${confirmModal.currency} price loading…`
                      : confirmForm.unit === 'usd'
                        ? <>≈ <strong>{(Number(confirmForm.amount) / confirmPrice).toFixed(8)} {confirmModal.currency}</strong> at ${Number(confirmPrice).toLocaleString('en-US')} (converted again at confirmation)</>
                        : <>≈ <strong>${(Number(confirmForm.amount) * confirmPrice).toFixed(2)}</strong> at ${Number(confirmPrice).toLocaleString('en-US')}</>}
                  </div>
                )}
              </div>
              <div className="admin-form-group">
                <label className="admin-label">Note (optional)</label>
                <input
                  className="admin-input"
                  value={confirmForm.note}
                  onChange={e => setConfirmForm(f => ({ ...f, note: e.target.value }))}
                  placeholder="Internal note…"
                />
              </div>
              {confirmErr && <div style={{ color: '#e53935', fontSize: 13, marginBottom: 12 }}>{confirmErr}</div>}
              <div className="admin-modal-actions">
                <button type="button" className="admin-btn admin-btn-secondary" onClick={() => setConfirmModal(null)}>Cancel</button>
                <button type="submit" className="admin-btn admin-btn-success" disabled={confirming}>
                  {confirming ? 'Confirming…' : 'Confirm & Credit'}
                </button>
              </div>
            </form>
          </div>
        </div>
      )}

      {/* Expire confirm */}
      {expireId && (
        <ConfirmModal
          title="Expire this deposit?"
          message="The deposit will be marked as expired and no funds will be credited."
          confirmLabel="Expire"
          danger
          loading={expiring}
          onConfirm={doExpire}
          onCancel={() => setExpireId(null)}
        />
      )}

      {/* Cleanup expired confirm */}
      {cleanupConfirm && (
        <ConfirmModal
          title="Cleanup all expired deposits?"
          message="All awaiting/partial deposits past their expiry time will be marked expired and their BlockCypher forwards will be deleted."
          confirmLabel="Cleanup Expired"
          danger
          loading={cleanupLoading}
          onConfirm={doCleanup}
          onCancel={() => setCleanupConfirm(false)}
        />
      )}

      {/* Verify HD key modal */}
      {verifyResult && (
        <div className="admin-modal-overlay" onClick={e => { if (e.target === e.currentTarget) setVerifyResult(null); }}>
          <div className="admin-modal">
            <div className="admin-modal-title" style={{ display: 'flex', alignItems: 'center', gap: 8 }}>
              <IconKey size={16} />HD Key Verification
              {!verifyResult.error && (
                <span style={{
                  marginLeft: 6, fontSize: 12, fontWeight: 700, borderRadius: 6, padding: '2px 8px',
                  background: verifyResult.match ? 'rgba(67,160,71,.15)' : 'rgba(229,57,53,.15)',
                  color: verifyResult.match ? '#2e7d32' : '#c62828',
                }}>
                  {verifyResult.match ? '✓ MATCH' : '✗ MISMATCH'}
                </span>
              )}
            </div>

            {verifyResult.error ? (
              <div style={{ background: 'rgba(229,57,53,.08)', border: '1px solid rgba(229,57,53,.25)', borderRadius: 8, padding: '10px 12px', color: '#c62828', fontSize: 13 }}>
                {verifyResult.error}
              </div>
            ) : (
              <>
                <div style={{
                  background: verifyResult.match ? 'rgba(67,160,71,.07)' : 'rgba(229,57,53,.07)',
                  border: `1px solid ${verifyResult.match ? 'rgba(67,160,71,.25)' : 'rgba(229,57,53,.25)'}`,
                  borderRadius: 8, padding: '10px 14px', marginBottom: 14, fontSize: 13,
                  color: verifyResult.match ? '#2e7d32' : '#b71c1c', lineHeight: 1.7,
                }}>
                  {verifyResult.match
                    ? 'The address stored in the database was correctly derived from the current HD seed. Sweep signing will work for this deposit.'
                    : 'The current HD seed derives a DIFFERENT address than what is stored. The private key no longer matches — sweep signing will fail. The original seed must be restored to recover funds from this address.'}
                </div>

                <div style={{ display: 'grid', gap: 10 }}>
                  {[
                    { label: 'Deposit', value: `#${verifyResult.depositId} · ${verifyResult.currency} · ${verifyResult.user?.username || '—'}` },
                    { label: 'Stored address', value: verifyResult.storedAddress },
                    { label: 'Derived address', value: verifyResult.derivedAddress },
                  ].map(({ label, value }) => (
                    <div key={label}>
                      <div style={{ fontSize: 11, fontWeight: 700, color: '#6c757d', textTransform: 'uppercase', letterSpacing: '.05em', marginBottom: 3 }}>{label}</div>
                      <div style={{
                        fontFamily: 'monospace', fontSize: 12, background: '#f4f6f9', borderRadius: 6,
                        padding: '6px 10px', wordBreak: 'break-all', lineHeight: 1.6,
                        color: label === 'Derived address' && !verifyResult.match ? '#c62828' : 'inherit',
                        border: label === 'Derived address' && !verifyResult.match ? '1px solid rgba(229,57,53,.3)' : '1px solid transparent',
                      }}>
                        {value}
                      </div>
                    </div>
                  ))}
                </div>

                {!verifyResult.match && (
                  <div style={{ marginTop: 14, background: 'rgba(229,57,53,.07)', border: '1px solid rgba(229,57,53,.2)', borderRadius: 8, padding: '10px 12px', fontSize: 12, color: '#7f0000', lineHeight: 1.6 }}>
                    <strong>Recovery steps:</strong><br />
                    1. Locate the original HD seed that was active when deposit #{verifyResult.depositId} was created.<br />
                    2. Temporarily restore it in Settings → Crypto → BTC HD Seed.<br />
                    3. Run the sweep, then restore the current seed.
                  </div>
                )}
              </>
            )}

            <div className="admin-modal-actions" style={{ marginTop: 16 }}>
              <button className="admin-btn admin-btn-secondary" onClick={() => setVerifyResult(null)}>Close</button>
            </div>
          </div>
        </div>
      )}

      {/* USD value modal */}
      {usdModal && (
        <InspectModal title="USD value" modal={usdModal} onClose={() => setUsdModal(null)}>
          {v => (
            <>
              <InfoRows rows={[
                ['Current price', v.price ? `${fmt(v.price)} / ${v.currency}` : 'unavailable'],
                v.expectedAmount != null && ['Expected', `${fmtC(v.expectedAmount)} ${v.currency} ≈ ${fmtUsd(v.expectedUsd)}`],
                ['Received (recorded)', `${fmtC(v.receivedAmount)} ${v.currency} ≈ ${fmtUsd(v.receivedUsd)}`, v.receivedAmount > 0 ? '#2e7d32' : undefined],
                ['Credited to customer', v.usdCredited > 0 ? fmt(v.usdCredited) : 'not credited yet', v.usdCredited > 0 ? '#2e7d32' : '#6c757d'],
                ['Status', <StatusBadge key="s" status={v.status} />],
              ]} />
              <div style={{ fontSize: 12, color: '#6c757d', marginBottom: 14, lineHeight: 1.6 }}>
                Values in USD use today's price ({v.priceSource || 'no price source available'}). The credited amount
                was computed with the price at confirmation time, so the two can differ.
                {v.currency === 'XMR' && ' XMR amounts are only known after manual verification in your Monero wallet.'}
              </div>
            </>
          )}
        </InspectModal>
      )}

      {/* On-chain wallet modal */}
      {chainModal && (
        <InspectModal title="Deposit wallet" modal={chainModal} onClose={() => setChainModal(null)}>
          {w => (
            <>
              <div style={{ background: '#f4f6f9', borderRadius: 8, padding: '8px 12px', marginBottom: 12, fontFamily: 'monospace', fontSize: 12, wordBreak: 'break-all' }}>
                {w.address}
              </div>
              <InfoRows rows={[
                ['Balance now', `${fmtC(w.total)} ${w.currency} ≈ ${fmtUsd(w.totalUsd)}`, w.total > 0 ? '#2e7d32' : '#6c757d'],
                w.unconfirmed ? ['Unconfirmed', `${fmtC(w.unconfirmed)} ${w.currency}`, '#e65100'] : null,
                w.totalReceived != null && ['Total ever received', `${fmtC(w.totalReceived)} ${w.currency} ≈ ${fmtUsd(w.totalReceivedUsd)}`],
                w.totalSent != null && ['Total sent out (swept)', `${fmtC(w.totalSent)} ${w.currency}`],
                ['Transactions', w.txCount],
                ['Recorded as received', `${fmtC(w.recordedReceived)} ${w.currency}`],
                ['Credited to customer', w.usdCredited > 0 ? fmt(w.usdCredited) : 'not credited yet'],
              ]} />
              <div style={{ fontSize: 12, color: '#6c757d', marginBottom: 14, lineHeight: 1.6 }}>
                Live data from {w.source}. A balance of 0 after a deposit usually means the funds were already swept
                — compare with "Total ever received".
              </div>
            </>
          )}
        </InspectModal>
      )}

      {/* View address modal */}
      {addrModal && (
        <div className="admin-modal-overlay" onClick={e => { if (e.target === e.currentTarget) setAddrModal(null); }}>
          <div className="admin-modal">
            <div className="admin-modal-title" style={{ display: 'flex', alignItems: 'center', gap: 10 }}>
              <CurrencyBadge currency={addrModal.currency} /> Deposit Address
            </div>
            <div style={{ background: '#f4f6f9', borderRadius: 8, padding: '12px 14px', marginBottom: 16, fontFamily: 'monospace', fontSize: 13, wordBreak: 'break-all', lineHeight: 1.6 }}>
              {addrModal.address}
            </div>
            <div className="admin-modal-actions">
              <button className="admin-btn admin-btn-secondary" onClick={() => setAddrModal(null)}>Close</button>
              <button className="admin-btn admin-btn-primary" onClick={copyAddr}>
                {copied ? '✓ Copied!' : 'Copy Address'}
              </button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}
