import React, { useState, useEffect, useRef } from 'react';
import { QRCodeSVG } from 'qrcode.react';
import { Link } from 'react-router-dom';
import { useApp } from '../context/AppContext';
import AccountSidebar from '../components/AccountSidebar';
import { api } from '../utils/api';

const CURRENCIES = [
  { key: 'BTC',  label: 'Bitcoin',  color: '#f7931a', note: 'suggested fee: 4 sat/vb' },
  { key: 'LTC',  label: 'Litecoin', color: '#345d9d', note: '' },
  { key: 'DOGE', label: 'Dogecoin', color: '#c2a633', note: '' },
  { key: 'ETH',  label: 'Ethereum', color: '#627eea', note: '' },
  { key: 'XMR',  label: 'Monero',   color: '#ff6600', note: '' },
];

const DEPOSIT_GUIDE = {
  BTC: {
    auto: true,
    time: '~10–60 min',
    steps: [
      'Copy the Bitcoin address above or scan the QR code with your wallet app.',
      'Send any amount of BTC to this address. You can send to it again later: each payment is credited.',
      'After 1 blockchain confirmation (usually 10–60 minutes), the BTC you sent (minus the deposit fee) is added to your balance automatically.',
      'Your balance keeps the BTC itself — its USD value follows the live market price until you spend it.',
    ],
    warning: 'Send only Bitcoin (BTC) to this address.',
  },
  LTC: {
    auto: true,
    time: '~5–30 min',
    steps: [
      'Copy the Litecoin address above or scan the QR code.',
      'Send any amount of LTC from your wallet. Each payment to this address is credited.',
      'After 1 confirmation on the Litecoin network (usually 5–30 min), your balance updates automatically.',
      'Your balance holds the LTC itself; its USD value follows the live market price.',
    ],
    warning: 'Send only Litecoin (LTC) to this address.',
  },
  DOGE: {
    auto: true,
    time: '~5–15 min',
    steps: [
      'Copy the Dogecoin address above or scan the QR code.',
      'Send any amount of DOGE. Each payment to this address is credited.',
      'After 1 confirmation (usually 5–15 min), your DOGE (minus the deposit fee) is credited automatically.',
      'Your balance holds the DOGE itself; its USD value follows the live market price.',
    ],
    warning: 'Send only Dogecoin (DOGE) to this address.',
  },
  ETH: {
    auto: true,
    time: '~1–5 min',
    steps: [
      'Copy the Ethereum address above or scan the QR code.',
      'Send any amount of ETH. Each payment to this address is credited.',
      'After 1 network confirmation (usually 1–5 minutes), your balance is updated automatically.',
      'Your balance holds the ETH itself; its USD value follows the live market price.',
    ],
    warning: 'Send only ETH to this address, not ERC-20 tokens.',
  },
  XMR: {
    auto: false,
    time: 'Within 24 hours',
    steps: [
      'Copy the Monero address above or scan the QR code.',
      'Send any amount of XMR from your Monero wallet.',
      'After sending, open a support ticket and include your Transaction ID (TX Hash) and the amount sent in XMR.',
      'Our team will verify the payment on the blockchain and manually credit your balance within 24 hours.',
    ],
    warning: 'Monero deposits are not automatic. You must contact support after sending — your balance will not update on its own.',
  },
};

const STATUS_ICONS = {
  BTC: () => (
    <svg width="18" height="18" viewBox="0 0 32 32"><circle cx="16" cy="16" r="16" fill="#F7931A"/><path d="M22.5 14.5c.4-2.5-1.5-3.8-4-4.7l.8-3.3-2-.5-.8 3.2-1.6-.4.8-3.2-2-.5-.8 3.2-3.3-.8-.5 2.1 1.4.4c.8.2 1 .7.9 1l-2.2 8.7c-.1.4-.5.8-1.2.6l-1.4-.3-.6 2.4 3.2.8-.8 3.3 2 .5.8-3.3 1.6.4-.8 3.2 2 .5.8-3.3c3.4.6 5.9.4 7-2.7.9-2.5-.1-3.9-1.8-4.8 1.3-.3 2.2-1.1 2.5-2.8z" fill="white"/></svg>
  ),
  DOGE: () => (
    <svg width="18" height="18" viewBox="0 0 32 32"><circle cx="16" cy="16" r="16" fill="#C2A633"/><text x="7" y="21" fontSize="14" fill="white" fontWeight="bold">D</text></svg>
  ),
  LTC: () => (
    <svg width="18" height="18" viewBox="0 0 32 32"><circle cx="16" cy="16" r="16" fill="#345D9D"/><path d="M13.5 20.5l1-4-1.5.5.5-2 1.5-.5 2-8h4l-1.5 6 1.5-.5-.5 2-1.5.5-1 4h7l-.5 2h-11l.5-2z" fill="white"/></svg>
  ),
  ETH: () => (
    <svg width="18" height="18" viewBox="0 0 32 32"><circle cx="16" cy="16" r="16" fill="#627EEA"/><path d="M16 7l-7 9.5 7-3.5 7 3.5L16 7z" fill="white" opacity="0.7"/><path d="M16 17.5L9 16.5l7 4 7-4-7 1z" fill="white"/><path d="M16 22l-7-4.5 7 8.5 7-8.5L16 22z" fill="white" opacity="0.7"/></svg>
  ),
  XMR: () => (
    <svg width="18" height="18" viewBox="0 0 32 32"><circle cx="16" cy="16" r="16" fill="#FF6600"/><path d="M16 8l-8 8v4h3v-4.5l5 5 5-5V20h3v-4l-8-8z" fill="white"/></svg>
  ),
};

function CheckCircleIcon() {
  return (
    <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="#43a047" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round">
      <path d="M22 11.08V12a10 10 0 1 1-5.93-9.14"/><polyline points="22 4 12 14.01 9 11.01"/>
    </svg>
  );
}
function MapIcon() {
  return (
    <svg width="16" height="16" viewBox="0 0 24 24" fill="transparent" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
      <polygon points="1 6 1 22 8 18 16 22 23 18 23 2 16 6 8 2 1 6"/><line x1="8" y1="2" x2="8" y2="18"/><line x1="16" y1="6" x2="16" y2="22"/>
    </svg>
  );
}
function CopyIcon() {
  return (
    <svg width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
      <rect x="9" y="9" width="13" height="13" rx="2" ry="2"/><path d="M5 15H4a2 2 0 0 1-2-2V4a2 2 0 0 1 2-2h9a2 2 0 0 1 2 2v1"/>
    </svg>
  );
}
function CloseIcon() {
  return (
    <svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round">
      <line x1="18" y1="6" x2="6" y2="18"/><line x1="6" y1="6" x2="18" y2="18"/>
    </svg>
  );
}

const TABS = ['Credit Deposits', 'Credit History', 'Legacy Credit History'];

const DEPOSIT_TERMS = [
  'You agree you are at least 21 years of age and do not conduct business with under age minors.',
  'Send any amount to the address displayed on the next page.',
  'Once it confirms on the blockchain, the crypto received is credited to your account minus the deposit fee shown below.',
  'Your balance is held in that crypto: its USD value follows the live market price and can go up or down until you spend it.',
  'At checkout, the order total is converted at the live price at that moment and that exact amount of crypto is deducted.',
  'If no transaction is received after 12 hours, this deposit will be cancelled.',
  'You can send to the same address more than once: each payment is credited after 1 confirmation (Monero: by hand).',
  'If a payment does not show up, press Check next to the deposit.',
];

function formatCountdown(expiresAt) {
  const diff = new Date(expiresAt) - Date.now();
  if (diff <= 0) return 'Expired';
  const h = Math.floor(diff / 3600000);
  const m = Math.floor((diff % 3600000) / 60000);
  const s = Math.floor((diff % 60000) / 1000);
  return `${String(h).padStart(2, '0')}:${String(m).padStart(2, '0')}:${String(s).padStart(2, '0')}`;
}

export default function WalletPage() {
  const { balance, holdings, depositFeePct, refreshBalance, setBalance, deposits, setDeposits, transactions, setTransactions, showToast } = useApp();
  const [selectedCurrency, setSelectedCurrency] = useState('DOGE');
  const [activeTab, setActiveTab]   = useState(0);
  const [copied, setCopied]         = useState(false);
  const [modalStep, setModalStep]   = useState(null); // null | 'select' | 'address'
  const [agreed, setAgreed]         = useState(false);
  const [currentDeposit, setCurrentDeposit] = useState(null);
  const [creating, setCreating]     = useState(false);
  const [timeLeft, setTimeLeft]     = useState('');
  const [checkingChain, setCheckingChain] = useState(false);
  const pollingRef = useRef(null);

  useEffect(() => {
    refreshBalance();
    api.get('/wallet/deposits').then(d => setDeposits(d.deposits || d || [])).catch(() => {});
    api.get('/wallet/transactions').then(d => setTransactions(d.transactions || d || [])).catch(() => {});
  }, [refreshBalance, setDeposits, setTransactions]);

  // Countdown timer for Step 2 modal
  useEffect(() => {
    if (!currentDeposit?.expiresAt || modalStep !== 'address') return;
    setTimeLeft(formatCountdown(currentDeposit.expiresAt));
    const id = setInterval(() => setTimeLeft(formatCountdown(currentDeposit.expiresAt)), 1000);
    return () => clearInterval(id);
  }, [currentDeposit?.expiresAt, modalStep]);

  // Blockchain polling — every 30s while deposit modal is open (except XMR)
  useEffect(() => {
    if (modalStep !== 'address' || !currentDeposit?.id || currentDeposit.currency === 'XMR') return;

    const poll = async () => {
      setCheckingChain(true);
      try {
        const result = await api.post(`/wallet/deposits/${currentDeposit.id}/check`);
        if (result.status === 'confirmed') {
          if (result.newBalance != null) setBalance(result.newBalance);
          refreshBalance();
          api.get('/wallet/deposits').then(d => setDeposits(d.deposits || d || [])).catch(() => {});
          showToast('Deposit confirmed! Your balance has been updated.', 'success');
          clearInterval(pollingRef.current);
          closeModal();
        } else if (result.status === 'expired') {
          showToast('Deposit has expired.', 'error');
          clearInterval(pollingRef.current);
          closeModal();
        }
      } catch { /* polling errors are silent */ }
      finally { setCheckingChain(false); }
    };

    pollingRef.current = setInterval(poll, 30000);
    return () => clearInterval(pollingRef.current);
  }, [modalStep, currentDeposit?.id]);

  const handleCopy = (text) => {
    navigator.clipboard?.writeText(text).then(() => {
      setCopied(true);
      setTimeout(() => setCopied(false), 2000);
    });
  };

  const handleCreateDeposit = async () => {
    setCreating(true);
    try {
      const data = await api.post('/wallet/deposit', { currency: selectedCurrency });
      const raw = data.deposit || data;
      // The server answers { depositId, … }: without `id` the blockchain check never ran
      const dep = { ...raw, id: raw.id ?? raw.depositId };
      setCurrentDeposit(dep);
      setDeposits(prev => [dep, ...prev.filter(d => d.id !== dep.id)]);
      setAgreed(false);
      setModalStep('address');
    } catch (err) {
      showToast(err.message || 'Failed to create deposit', 'error');
    } finally {
      setCreating(false);
    }
  };

  // Looks at the address again: a payment sent to it once more is credited
  const [checkingId, setCheckingId] = useState(null);
  const recheck = async dep => {
    setCheckingId(dep.id);
    try {
      const r = await api.post(`/wallet/deposits/${dep.id}/check`);
      if (r.newBalance != null) setBalance(r.newBalance);
      refreshBalance();
      api.get('/wallet/deposits').then(d => setDeposits(d.deposits || d || [])).catch(() => {});
      showToast(r.credited > 0 ? `${r.credited} new payment${r.credited > 1 ? 's' : ''} credited.` : r.pending ? 'A payment is waiting for its confirmation.' : 'No new payment on this address.', r.credited > 0 ? 'success' : 'info');
    } catch (e) {
      showToast(e.message || 'Check failed', 'error');
    } finally { setCheckingId(null); }
  };

  // A pending deposit's address stays valid until it expires: reopen its QR and checks
  const isOpen = dep => ['awaiting', 'partial'].includes(dep.status) && dep.address && dep.address !== 'pending'
    && (!dep.expiresAt || new Date(dep.expiresAt) > Date.now());
  const showDeposit = dep => {
    setCurrentDeposit(dep);
    setSelectedCurrency(dep.currency);
    setModalStep('address');
  };

  const closeModal = () => {
    clearInterval(pollingRef.current);
    setModalStep(null);
    setAgreed(false);
    setCheckingChain(false);
  };

  const depositAddress  = currentDeposit?.address || '';
  const depositCurrency = currentDeposit?.currency || selectedCurrency;
  const currencyColor   = CURRENCIES.find(c => c.key === depositCurrency)?.color || '#888';

  const URI_SCHEME = { BTC: 'bitcoin', LTC: 'litecoin', DOGE: 'dogecoin', ETH: 'ethereum', XMR: 'monero' };
  const depositQrValue = depositAddress
    ? `${URI_SCHEME[depositCurrency] || depositCurrency.toLowerCase()}:${depositAddress}`
    : '';

  return (
    <main className="main-content">
      <div className="account-layout">
        <AccountSidebar />

        <div className="account-main">
          <h3 className="account-page-title">Credits</h3>

          <div className="credits-top-grid">
            {/* Available Credits card */}
            <div className="credits-balance-card">
              <h4 className="credits-card-heading">Available Credits</h4>
              <div className="credits-balance-body">
                <div className="credits-balance-graphic">
                  <svg width="120" height="86" viewBox="0 0 236 168" fill="none" xmlns="http://www.w3.org/2000/svg">
                    <rect x="8" y="8" width="220" height="152" rx="16" fill="#E8F4FF" stroke="#0171E3" strokeWidth="1.5"/>
                    <circle cx="118" cy="84" r="40" fill="#0171E3" opacity="0.12"/>
                    <circle cx="118" cy="84" r="24" fill="#0171E3" opacity="0.2"/>
                    <path d="M108 84l6 6 12-12" stroke="#0171E3" strokeWidth="3" strokeLinecap="round" strokeLinejoin="round"/>
                    <rect x="28" y="28" width="60" height="8" rx="4" fill="#0171E3" opacity="0.2"/>
                    <rect x="28" y="44" width="40" height="6" rx="3" fill="#0171E3" opacity="0.12"/>
                    <rect x="148" y="128" width="60" height="8" rx="4" fill="#0171E3" opacity="0.2"/>
                  </svg>
                </div>
                <h2 className="credits-balance-amount">${Number(balance).toFixed(2)}</h2>
              </div>
              {holdings.length > 0 ? (
                <ul className="credits-holdings">
                  {holdings.map(h => (
                    <li key={h.currency} className="credits-holding-row">
                      <span className="credits-holding-coin">{React.createElement(STATUS_ICONS[h.currency] || (() => null))} {h.amount} {h.currency}</span>
                      <span className="credits-holding-usd">
                        {h.usd != null ? `$${h.usd.toFixed(2)}` : 'price unavailable'}
                        {h.price != null && <small> @ ${Number(h.price).toLocaleString('en-US', { maximumFractionDigits: h.price < 1 ? 4 : 2 })}</small>}
                      </span>
                    </li>
                  ))}
                </ul>
              ) : (
                <p className="credits-holdings-empty">Add funds to start shopping.</p>
              )}
              <p className="credits-live-note">Live value · updates every 30s with the market price</p>
            </div>

            {/* Load Credits card */}
            <div className="credits-load-card">
              <div className="credits-load-header">
                <h4 className="credits-card-heading">Load Credits</h4>
                <button className="credits-walkthrough-btn"><MapIcon /> Guided walkthrough</button>
              </div>

              <p className="credits-load-subtitle">
                Your balance holds the crypto you send and its USD value follows the live market price.
                {depositFeePct != null && depositFeePct > 0 && (
                  <> A <strong>{depositFeePct}% deposit fee</strong> is deducted from each deposit when it confirms.</>
                )}
              </p>

              <div className="credits-currency-list">
                {CURRENCIES.map(c => (
                  <label key={c.key} className={`credits-currency-row${selectedCurrency === c.key ? ' selected' : ''}`}>
                    <input type="radio" name="currency" value={c.key} checked={selectedCurrency === c.key} onChange={() => setSelectedCurrency(c.key)} className="credits-radio" />
                    <span className="credits-currency-icon">{React.createElement(STATUS_ICONS[c.key])}</span>
                    <span className="credits-currency-info">
                      <span className="credits-currency-name">{c.label}</span>
                      <span className="credits-currency-ticker">
                        ({c.key}){c.note && <span className="credits-currency-note"> · {c.note}</span>}
                      </span>
                    </span>
                  </label>
                ))}
              </div>

              <div className="credits-status-section">
                <span className="credits-status-label">System status</span>
                <div className="credits-status-list">
                  {CURRENCIES.map(c => (
                    <div key={c.key} className="credits-status-item">
                      {React.createElement(STATUS_ICONS[c.key])}
                      <CheckCircleIcon />
                    </div>
                  ))}
                </div>
              </div>

              <button className="credits-new-deposit-btn" onClick={() => setModalStep('select')}>
                Add Funds
              </button>

              {currentDeposit && depositAddress && depositAddress !== 'pending' && (
                <div className="credits-address-section">
                  <div className="credits-address-label">Your {depositCurrency} deposit address</div>
                  <div className="credits-address-row">
                    <code className="credits-address-code">{depositAddress}</code>
                    <button className={`credits-copy-btn${copied ? ' copied' : ''}`} onClick={() => handleCopy(depositAddress)}>
                      {copied ? '✓' : <CopyIcon />}
                    </button>
                  </div>
                </div>
              )}
            </div>
          </div>

          {/* Tabs + table */}
          <div className="credits-history-section">
            <div className="credits-tabs">
              {TABS.map((tab, i) => (
                <button key={tab} className={`credits-tab${activeTab === i ? ' active' : ''}`} onClick={() => setActiveTab(i)}>
                  {tab}
                </button>
              ))}
            </div>

            <div className="credits-table-wrap">
              {activeTab === 0 && (
                <table className="credits-table">
                  <thead>
                    <tr><th>Id</th><th>Status</th><th>Currency</th><th>Received</th><th>Address</th><th>Created</th><th>Details</th></tr>
                  </thead>
                  <tbody>
                    {deposits.length === 0 ? (
                      <tr><td colSpan={7} className="credits-table-empty">No deposits yet.</td></tr>
                    ) : deposits.map(dep => (
                      <tr key={dep.id}>
                        <td className="credits-table-id">{String(dep.id).slice(-8)}</td>
                        <td>
                          <span className={`credits-status-badge ${dep.status || 'pending'}`}>
                            {dep.status || 'pending'}
                          </span>
                        </td>
                        <td>{dep.currency}</td>
                        <td>{Number(dep.amountReceived) > 0 ? `${Number(dep.amountReceived)} ${dep.currency}` : '—'}</td>
                        <td className="credits-table-addr">{dep.address ? dep.address.slice(0, 14) + '…' : '—'}</td>
                        <td>{dep.createdAt ? new Date(dep.createdAt).toLocaleDateString('en-US', { month: 'short', day: 'numeric', year: 'numeric' }) : '—'}</td>
                        <td>
                          {dep.orderId && isOpen(dep) ? (
                            <Link className="credits-details-btn" to={`/orders/${dep.orderId}/pay`}>Pay order</Link>
                          ) : isOpen(dep) ? (
                            <button className="credits-details-btn" onClick={() => showDeposit(dep)}>Show</button>
                          ) : dep.currency !== 'XMR' && dep.address && dep.address !== 'pending' ? (
                            <button className="credits-details-btn" disabled={checkingId === dep.id} onClick={() => recheck(dep)}>{checkingId === dep.id ? 'Checking…' : 'Check'}</button>
                          ) : (
                            <button className="credits-details-btn" onClick={() => dep.address && handleCopy(dep.address)}>Copy</button>
                          )}
                        </td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              )}
              {activeTab === 1 && (
                <table className="credits-table">
                  <thead>
                    <tr><th>Id</th><th>Type</th><th>Amount</th><th>Date</th><th>Note</th></tr>
                  </thead>
                  <tbody>
                    {transactions.length === 0 ? (
                      <tr><td colSpan={5} className="credits-table-empty">No credit history yet.</td></tr>
                    ) : transactions.map(txn => (
                      <tr key={txn.id}>
                        <td className="credits-table-id">{String(txn.id).slice(-8)}</td>
                        <td>{txn.type}</td>
                        <td style={{ color: Number(txn.amount) >= 0 ? '#43a047' : '#e53935', fontWeight: 600 }}>
                          {Number(txn.amount) >= 0 ? '+' : ''}${Math.abs(Number(txn.amount)).toFixed(2)}
                        </td>
                        <td>{txn.createdAt || txn.date ? new Date(txn.createdAt || txn.date).toLocaleDateString() : '—'}</td>
                        <td style={{ color: 'var(--text-muted)', fontSize: 13 }}>{txn.note || txn.description || '—'}</td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              )}
              {activeTab === 2 && (
                <div className="credits-table-empty">No legacy credit history.</div>
              )}
            </div>
          </div>
        </div>
      </div>

      {/* ── Step 1: currency selection + terms ─────────────────────────────────── */}
      {modalStep === 'select' && (
        <div className="modal-overlay" onClick={closeModal}>
          <div className="modal-card" onClick={e => e.stopPropagation()}>
            <button className="modal-close" onClick={closeModal}><CloseIcon /></button>
            <h3 className="modal-title">Add Funds</h3>
            <p className="modal-subtitle">Select a cryptocurrency to generate your deposit address.</p>

            {/* Currency badges */}
            <div style={{ display: 'flex', flexWrap: 'wrap', gap: 8, margin: '16px 0' }}>
              {CURRENCIES.map(c => (
                <button
                  key={c.key}
                  onClick={() => setSelectedCurrency(c.key)}
                  style={{
                    display:      'flex',
                    alignItems:   'center',
                    gap:          6,
                    padding:      '6px 14px',
                    borderRadius: 20,
                    border:       `2px solid ${selectedCurrency === c.key ? c.color : 'transparent'}`,
                    background:   selectedCurrency === c.key ? `${c.color}22` : 'var(--bg-card, #f5f5f5)',
                    color:        selectedCurrency === c.key ? c.color : 'inherit',
                    fontWeight:   selectedCurrency === c.key ? 700 : 400,
                    cursor:       'pointer',
                    fontSize:     13,
                    transition:   'all .15s',
                  }}
                >
                  {React.createElement(STATUS_ICONS[c.key])}
                  {c.key}
                </button>
              ))}
            </div>

            <ol className="deposit-terms">
              {DEPOSIT_TERMS.map((t, i) => <li key={i}>{i + 1}. {t}</li>)}
            </ol>

            {depositFeePct != null && (
              <div className="deposit-fee-box">
                <strong>Deposit fee: {depositFeePct}%</strong>
                <span>
                  Example: send 1.00 {selectedCurrency} → {(1 - depositFeePct / 100).toFixed(4).replace(/0+$/, '').replace(/\.$/, '')} {selectedCurrency} is added to your balance.
                </span>
              </div>
            )}

            <label className="deposit-agree">
              <input type="checkbox" checked={agreed} onChange={e => setAgreed(e.target.checked)} />
              <span>I have read and agree to the deposit terms</span>
            </label>

            <button
              className="deposit-create-btn"
              disabled={!agreed || creating}
              onClick={handleCreateDeposit}
            >
              {creating ? 'Generating…' : 'Generate Address'}
            </button>
          </div>
        </div>
      )}

      {/* ── Step 2: QR code + address + countdown ──────────────────────────────── */}
      {modalStep === 'address' && currentDeposit && (
        <div className="modal-overlay" onClick={closeModal}>
          <div className="modal-card" onClick={e => e.stopPropagation()}>
            <button className="modal-close" onClick={closeModal}><CloseIcon /></button>

            <div style={{ display: 'flex', alignItems: 'center', gap: 8, marginBottom: 4 }}>
              <h3 className="modal-title" style={{ margin: 0 }}>Deposit</h3>
              <span style={{
                background:   currencyColor,
                color:        '#fff',
                borderRadius: 12,
                padding:      '2px 10px',
                fontWeight:   700,
                fontSize:     13,
              }}>
                {depositCurrency}
              </span>
            </div>

            <p className="modal-subtitle" style={{ marginBottom: 16 }}>
              Send {depositCurrency} to the address below. Do not reuse this address.
            </p>

            {/* QR code */}
            <div style={{ display: 'flex', justifyContent: 'center', margin: '12px 0' }}>
              <QRCodeSVG value={depositQrValue} size={180} className="wallet-qr-svg" />
            </div>

            {/* Address + copy */}
            <div style={{ display: 'flex', alignItems: 'center', gap: 8, margin: '12px 0', flexWrap: 'wrap' }}>
              <code style={{
                flex:       1,
                background: 'var(--bg-card, #f5f5f5)',
                padding:    '8px 12px',
                borderRadius: 8,
                fontSize:   12,
                wordBreak:  'break-all',
                lineHeight: 1.5,
              }}>
                {depositAddress}
              </code>
              <button
                className={`credits-copy-btn${copied ? ' copied' : ''}`}
                onClick={() => handleCopy(depositAddress)}
                style={{ flexShrink: 0 }}
              >
                {copied ? '✓' : <CopyIcon />}
              </button>
            </div>

            {/* Countdown */}
            <div style={{ textAlign: 'center', margin: '12px 0' }}>
              <span style={{ fontSize: 12, color: 'var(--text-muted)' }}>Expires in </span>
              <span style={{ fontFamily: 'monospace', fontWeight: 700, fontSize: 16 }}>{timeLeft}</span>
            </div>

            {/* Polling indicator */}
            {checkingChain && (
              <div style={{ textAlign: 'center', fontSize: 12, color: '#1976d2', marginBottom: 8 }}>
                <span style={{ display: 'inline-flex', alignItems: 'center', gap: 6, background: 'rgba(25,118,210,.08)', borderRadius: 20, padding: '4px 12px' }}>
                  <span style={{ display: 'inline-block', width: 8, height: 8, borderRadius: '50%', background: '#1976d2', animation: 'pulse 1s infinite' }} />
                  Checking blockchain for new confirmations…
                </span>
              </div>
            )}

            {/* How it works guide */}
            {(() => {
              const guide = DEPOSIT_GUIDE[depositCurrency];
              if (!guide) return null;
              return (
                <div style={{ marginTop: 16 }}>
                  <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'space-between', marginBottom: 10 }}>
                    <span style={{ fontWeight: 700, fontSize: 13 }}>How it works</span>
                    <span style={{
                      fontSize: 11, fontWeight: 700, borderRadius: 20, padding: '2px 10px',
                      background: guide.auto ? 'rgba(67,160,71,.12)' : 'rgba(251,140,0,.12)',
                      color:      guide.auto ? '#43a047'             : '#fb8c00',
                    }}>
                      {guide.auto ? `⚡ Auto-confirmed · ${guide.time}` : `👤 Manual review · ${guide.time}`}
                    </span>
                  </div>

                  <ol style={{ margin: 0, paddingLeft: 18, display: 'flex', flexDirection: 'column', gap: 6 }}>
                    {guide.steps.map((step, i) => (
                      <li key={i} style={{ fontSize: 13, color: 'var(--text-body, #333)', lineHeight: 1.5 }}>{step}</li>
                    ))}
                  </ol>

                  <div style={{
                    marginTop: 12, fontSize: 12, lineHeight: 1.5, borderRadius: 8,
                    padding: '8px 12px',
                    background: guide.auto ? 'rgba(67,160,71,.08)' : 'rgba(229,57,53,.08)',
                    color:      guide.auto ? '#2e7d32'             : '#c62828',
                    borderLeft: `3px solid ${guide.auto ? '#43a047' : '#e53935'}`,
                  }}>
                    {guide.warning}
                  </div>

                  {!guide.auto && (
                    <a
                      href="/support"
                      style={{
                        display: 'block', marginTop: 12, textAlign: 'center',
                        background: '#ff6600', color: '#fff', borderRadius: 8,
                        padding: '10px 0', fontWeight: 700, fontSize: 13, textDecoration: 'none',
                      }}
                    >
                      Open a Support Ticket →
                    </a>
                  )}
                </div>
              );
            })()}
          </div>
        </div>
      )}
    </main>
  );
}
